real DenseMatrix::dotRow(const Vector& vec, int64_t i) const {
  assert(i >= 0);
  assert(i < m_);
  assert(vec.size() == n_);
  real res = 0.0;
  for (int64_t j = 0; j < n_; j++) {
    res += at(i, j) * vec[j];
  }
  if (std::isnan(res)) {
    throw EncounteredNaNError();
  }
  return res;
}
